@code {
    [SupplyParameterFromQuery(Name = "filter")] public string? Filter { get; set; }
    private IQueryable<Stock> North => Stock.North.Where(x => Filter == null || x.Group == Filter).AsQueryable();
    private IQueryable<Stock> South => Stock.South.Where(x => Filter == null || x.Group == Filter).AsQueryable();
}
<section id="@Id">
    <h2>@Id stores</h2>
    <QuickGrid Items="Items" Pagination="page">
        <PropertyColumn Property="x => x.Code" Title="code" Sortable="true" />
        <PropertyColumn Property="x => x.Units" Title="units" Sortable="true" />
    </QuickGrid>
    <Paginator State="page" />
</section>
@code {
    [Parameter, EditorRequired] public string Id { get; set; } = "";
    [Parameter, EditorRequired] public IQueryable<Stock> Items { get; set; } = default!;
